<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import { useRoute } from 'vue-router'
import { researchApi,type RecordItem } from '@/api/research'
const route=useRoute(),items=ref<RecordItem[]>([]),error=ref(''),busy=ref(false),page=ref(0)
const question=ref(''),answer=ref(''),subject=ref('综合学习'),sourceKind=ref(''),sourceId=ref(''),editing=ref<RecordItem>(),revealed=ref(false),filter=ref('due')
const selected=ref<RecordItem|null>(null)
const filtered=computed(()=>items.value.filter(i=>filter.value==='all'||filter.value==='mistakes'&&i.data.mistakes>0||filter.value==='due'&&new Date(i.data.due).getTime()<=Date.now()))
async function load(){busy.value=true;try{items.value=await researchApi.records('CARD',page.value)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function edit(i:RecordItem){editing.value=i;question.value=i.data.question;answer.value=i.data.answer;subject.value=i.data.subject;sourceKind.value=i.data.sourceKind||'';sourceId.value=i.data.sourceId||''}
function reset(){editing.value=undefined;question.value='';answer.value='';sourceKind.value='';sourceId.value=''}
async function save(){busy.value=true;error.value='';try{await researchApi.save('CARD',question.value.slice(0,180),{question:question.value,answer:answer.value,subject:subject.value,sourceKind:sourceKind.value,sourceId:sourceId.value},editing.value);reset();await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function grade(n:number){if(!selected.value)return;busy.value=true;try{await researchApi.grade(selected.value,n);selected.value=null;revealed.value=false;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(i:RecordItem){if(!confirm('删除这张复习卡及其学习记录？'))return;busy.value=true;try{await researchApi.delete(i);await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{await load();const id=String(route.query.note||route.query.source||'');if(id){try{const s=await researchApi.source(String(route.query.type||'NOTE'),id);sourceId.value=id;sourceKind.value=s.kind;question.value=s.title;answer.value=s.body.slice(0,10000)}catch(e){error.value=(e as Error).message}}})
</script>
<template><div><p v-if="error" role="alert" class="inline-alert inline-alert--error">{{ error }}</p><div class="research-columns"><section>
 <div class="research-section-title"><h2>每天积累一点</h2><select v-model="filter" class="field-input" aria-label="复习筛选"><option value="due">到期复习</option><option value="mistakes">薄弱知识点</option><option value="all">全部复习卡</option></select></div>
 <div v-if="selected" class="research-card review-card"><small>{{ selected.data.subject }}</small><h3>{{ selected.data.question }}</h3><button v-if="!revealed" class="button button--dark" @click="revealed=true">显示答案</button><template v-else><pre>{{ selected.data.answer }}</pre><p class="research-hint">根据自己的回忆情况评分，系统安排下次复习。</p><div class="research-actions"><button v-for="(label,index) in ['忘记了','有点难','记得','很熟练']" :key="label" class="button button--ghost" :disabled="busy" @click="grade(index)">{{ label }}</button></div></template><RouterLink v-if="selected.data.sourceId" :to="{path:'/app/research',query:{tab:'search',source:selected.data.sourceId,type:selected.data.sourceKind}}">返回来源 →</RouterLink><button class="button button--ghost" @click="selected=null">结束本张复习</button></div>
 <p v-if="!filtered.length" class="research-empty">本页没有需要复习的卡片。可以新建，或从笔记与搜索结果中制作。</p>
 <article v-for="i in filtered" :key="i.id" class="research-list-row"><div><button class="result-title" @click="selected=i;revealed=false">{{ i.title }}</button><p>{{ i.data.subject }} · 已复习 {{ i.data.reviews }} 次 · 下次 {{ new Date(i.data.due).toLocaleString() }}</p></div><div class="research-actions"><button class="button button--ghost" @click="edit(i)">编辑</button><button class="button button--ghost" :disabled="busy" @click="remove(i)">删除</button></div></article>
 <div class="research-pagination"><button class="button button--ghost" :disabled="!page||busy" @click="page--;load()">上一页</button><span>第 {{ page+1 }} 页 · 每页 50 张</span><button class="button button--ghost" :disabled="items.length<50||busy" @click="page++;load()">下一页</button></div>
 </section><form class="research-form research-card" @submit.prevent="save"><h2>{{ editing?'编辑复习卡':'制作一张复习卡' }}</h2><label>问题<textarea v-model="question" class="field-input" maxlength="2000" required placeholder="用自己的话提出一个问题"/></label><label>答案<textarea v-model="answer" class="field-input" maxlength="10000" required placeholder="写下解释、例子或代码"/></label><label>学科<input v-model="subject" class="field-input" maxlength="80"/></label><p v-if="sourceId" class="research-hint">已关联原始资料，复习时可返回查看。</p><div class="research-actions"><button class="button button--dark" :disabled="busy">保存复习卡</button><button type="button" class="button button--ghost" @click="reset">清空表单</button></div></form></div></div></template>
<style scoped>.review-card h3{font-size:20px;line-height:1.8}.review-card pre{white-space:pre-wrap;overflow-wrap:anywhere;font-family:inherit;font-size:14px;line-height:1.9}.review-card>a{display:block;margin:20px 0}.research-section-title select{width:auto;max-width:180px}.research-actions{flex-wrap:wrap}.research-form{align-self:start}</style>
